  "anomalies": [
    {
      "category": "bridged_nets",
      "components": [
        "U4",
        "J6",
        "J14",
        "U3"
      ],
      "pins": [
        "U4.7",
        "U4.1",
        "U4.2",
        "J6.2",
        "J14.2",
        "U3.13"
      ],
      "nets": [
        "/Microcontroller/NET0002",
        "Net-(J14-Pin_2)"
      ],
      "observed": "U4 pin 7 (OUT) is connected to J14 pin 2 on Net-(J14-Pin_2), while J6 pin 2 is connected to /Microcontroller/NET0002 together with U3 GPIO1 and U4 IN/DIAG_EN.",
      "expected": "The specification states the TPS1H200 OUT pin 7 feeds the heater connector J6 pin 2; J6 pin 2 should be on the heater-output net, not on the GPIO1/IN/DIAG_EN control net.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (code \"4\") (name \"/Microcontroller/NET0002\")"
        },
        {
          "source": "netlist",
          "quote": "(node (ref \"J6\") (pin \"2\") (pinfunction \"Pin_2\") (pintype \"passive\"))"
        },
        {
          "source": "netlist",
          "quote": "(node (ref \"U4\") (pin \"1\") (pinfunction \"IN\") (pintype \"input\"))"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"27\") (name \"Net-(J14-Pin_2)\")"
        },
        {
          "source": "netlist",
          "quote": "(node (ref \"U4\") (pin \"7\") (pinfunction \"OUT\") (pintype \"output\"))"
        },
        {
          "source": "spec",
          "quote": "OUT (pin 7) feeds the heater connector J6 pin 2"
        }
      ],
      "impact": "If a heater is connected to the specified J6 terminal, it is not driven by the high-side switch and a 12 V load can be applied directly to ESP32 GPIO1 and the switch input pins, likely damaging the MCU or leaving the heater uncontrolled; the actual switch output appears on J14 instead.",
      "confidence": 0.78
    }
  ],
  "summary": "The power, thermocouple, SPI, fan, and buck/mux nets match the specification, but the heater switch output is connected to J14 while the specified heater connector J6 is tied to the GPIO1/IN/DIAG_EN control net, a likely wiring/reference anomaly."
}

